{"content":"import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.BOOKS_FILE || join(__dirname, 'books.json');

/**
 * @typedef {Object} Book
 * @property {string} id
 * @property {string} title
 * @property {string} author
 * @property {string} notes
 * @property {boolean} finished
 */

/**
 * Read all books from the JSON file.
 * If the file does not exist yet, return an empty list.
 * @returns {Book[]}
 */
export function readBooks() {
  if (!existsSync(DATA_FILE)) return [];
  try {
    const raw = readFileSync(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

/**
 * Persist the full books array to the JSON file.
 * @param {Book[]} books
 */
function save(books) {
  writeFileSync(DATA_FILE, JSON.stringify(books, null, 2) + '\n', 'utf8');
}

/**
 * Append a book and persist.
 * @param {Book} book
 */
export function addBook(book) {
  const books = readBooks();
  books.push(book);
  save(books);
}

/**
 * Mark a book (by id) as finished and persist.
 * @param {string} id
 */
export function markFinished(id) {
  const books = readBooks();
  const book = books.find((b) => b.id === id);
  if (book) {
    book.finished = true;
    save(books);
  }
}

export { DATA_FILE };
